<?php
if ( ! defined( 'ABSPATH' ) ) exit;

interface SurveyJS_File_Storage {

    /**
     * @return string|WP_Error The key of the saved file: [A-Za-z0-9][A-Za-z0-9._-]*, unique, generated by the storage.
     */
    public function save( string $tmp_path, string $ext, array $context );

    public function exists( string $key ): bool;

    /**
     * @return int|false
     */
    public function size( string $key );

    /**
     * Sends the file (or redirects to it) and exits. $headers are already filtered with surveyjs_file_serve_headers.
     */
    public function serve( string $key, string $download_name, string $disposition, array $headers );

    /**
     * @return string|false A path that PHP functions without stream wrappers (PHPMailer, PDF tools) can read until the request ends.
     */
    public function local_path( string $key );

    public function delete( string $key ): bool;
}

class SurveyJS_Uploads_Storage implements SurveyJS_File_Storage {

    const SUBDIR        = '/surveyjs';
    const GUARD_VERSION = '2';
    const GUARD_OPTION  = 'surveyjs_upload_guard_version';
    const CHUNK_SIZE    = MB_IN_BYTES;
    const NAME_ATTEMPTS = 5;

    public function dir() {
        $upload_dir = wp_upload_dir( null, false );
        if ( ! empty( $upload_dir['error'] ) ) {
            return null;
        }
        $dir = apply_filters(
            'surveyjs_upload_dir',
            array(
                'path' => $upload_dir['basedir'] . self::SUBDIR,
                'url'  => $upload_dir['baseurl'] . self::SUBDIR,
            )
        );
        if ( ! is_array( $dir ) || empty( $dir['path'] ) || ! is_string( $dir['path'] ) ) {
            return null;
        }
        return array(
            'path' => untrailingslashit( $dir['path'] ),
            'url'  => untrailingslashit( (string) ( $dir['url'] ?? '' ) ),
        );
    }

    public function save( string $tmp_path, string $ext, array $context ) {
        $dir = $this->dir();
        if ( null === $dir || ! wp_mkdir_p( $dir['path'] ) ) {
            return new WP_Error( 'surveyjs_no_upload_dir', __( 'The upload folder could not be created.', 'surveyjs' ) );
        }
        $this->protect( $dir['path'] );

        for ( $attempt = 0; $attempt < self::NAME_ATTEMPTS; $attempt++ ) {
            $key = strtolower( wp_generate_password( 32, false ) ) . '.' . $ext;
            $path = $dir['path'] . '/' . $key;
            if ( ! file_exists( $path ) ) {
                return copy( $tmp_path, $path ) ? $key : new WP_Error( 'surveyjs_not_saved', __( 'The file could not be saved.', 'surveyjs' ) );
            }
        }
        return new WP_Error( 'surveyjs_not_saved', __( 'The file could not be saved.', 'surveyjs' ) );
    }

    public function exists( string $key ): bool {
        $path = $this->path( $key );
        return null !== $path && is_file( $path );
    }

    public function size( string $key ) {
        $path = $this->path( $key );
        return null !== $path && is_file( $path ) ? filesize( $path ) : false;
    }

    public function serve( string $key, string $download_name, string $disposition, array $headers ) {
        $path = $this->path( $key );
        // WP_Filesystem has no streaming read, and readfile() on a stream wrapper (vip://, s3://) may buffer the whole file in memory.
        $handle = null === $path ? false : fopen( $path, 'rb' ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fopen
        if ( false === $handle ) {
            wp_die( esc_html__( 'File not found.', 'surveyjs' ), '', array( 'response' => 404 ) );
        }
        $size = filesize( $path );
        if ( false !== $size ) {
            $headers = array( 'Content-Length' => (string) $size ) + $headers;
        }
        foreach ( $headers as $name => $value ) {
            header( $name . ': ' . $value );
        }
        $offloaded = isset( $headers['X-Accel-Redirect'] ) || isset( $headers['X-Sendfile'] );
        $head = 'HEAD' === sanitize_text_field( wp_unslash( $_SERVER['REQUEST_METHOD'] ?? '' ) );
        if ( ! $offloaded && ! $head ) {
            while ( ! feof( $handle ) ) {
                $chunk = fread( $handle, self::CHUNK_SIZE ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fread
                if ( false === $chunk ) {
                    break;
                }
                echo $chunk; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- binary file contents.
                flush();
            }
        }
        fclose( $handle ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
        exit;
    }

    public function local_path( string $key ) {
        $path = $this->path( $key );
        if ( null === $path || ! is_file( $path ) ) {
            return false;
        }
        return wp_is_stream( $path ) ? SurveyJS_Uploaded_Files::temp_copy( $path ) : $path;
    }

    public function delete( string $key ): bool {
        $path = $this->path( $key );
        if ( null === $path ) {
            return false;
        }
        if ( is_file( $path ) ) {
            wp_delete_file( $path );
        }
        return ! is_file( $path );
    }

    public function path( $key ) {
        $dir = $this->dir();
        return null !== $dir && SurveyJS_Uploaded_Files::is_valid_name( $key ) ? $dir['path'] . '/' . $key : null;
    }

    // .htaccess works only on Apache, and stream wrappers (vip://, s3://) serve files without a web server that reads it.
    public function protect( $dir ) {
        if ( wp_is_stream( $dir ) ) {
            return;
        }
        $guards = array(
            '.htaccess' => "<IfModule mod_authz_core.c>\n    Require all denied\n</IfModule>\n<IfModule !mod_authz_core.c>\n    Order deny,allow\n    Deny from all\n</IfModule>\n<Files *>\n    SetHandler none\n    SetHandler default-handler\n    Options -ExecCGI\n    RemoveHandler .php .phtml .php3 .php4 .php5 .php7 .phps\n    RemoveType .php .phtml\n    php_flag engine off\n</Files>\n",
            'index.php' => "<?php\n// Silence is golden.\n",
        );

        $outdated = array();
        foreach ( $guards as $name => $contents ) {
            $path = $dir . '/' . $name;
            if ( ! file_exists( $path ) || ( '.htaccess' === $name && file_get_contents( $path ) !== $contents ) ) { // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents,WordPressVIPMinimum.Performance.FetchingRemoteData.FileGetContentsUnknown -- a local file in the upload folder, never a URL.
                $outdated[ $path ] = $contents;
            }
        }
        if ( ! $outdated ) {
            return;
        }

        if ( ! function_exists( 'WP_Filesystem' ) ) {
            require_once ABSPATH . 'wp-admin/includes/file.php';
        }
        if ( ! WP_Filesystem() ) {
            return;
        }

        global $wp_filesystem;
        foreach ( $outdated as $path => $contents ) {
            $wp_filesystem->put_contents( $path, $contents, FS_CHMOD_FILE );
        }
    }

    public function maybe_update_guards() {
        if ( self::GUARD_VERSION === get_option( self::GUARD_OPTION ) ) {
            return;
        }
        $dir = $this->dir();
        if ( null !== $dir && ! wp_is_stream( $dir['path'] ) && is_dir( $dir['path'] ) ) {
            $this->protect( $dir['path'] );
        }
        update_option( self::GUARD_OPTION, self::GUARD_VERSION );
    }
}
